const TPROF=[[0,15],[11,-56],[20,-56],[32,-44],[50,-2],[55,-2],[80,-86],[90,-86],[120,60]];
const tAt=h=>{for(let i=1;i<TPROF.length;i++)if(h<=TPROF[i][0]){const a=TPROF[i-1],b=TPROF[i];return a[1]+(b[1]-a[1])*(h-a[0])/(b[0]-a[0]);}return 60;};
const LAYERS=[[0,11,'Тропосфера','Нижний, самый плотный слой: около 80% всей массы воздуха и почти весь водяной пар. Здесь облака, дожди, ветер — здесь «делается» погода. Толщина: над экватором около 18 км, над полюсами около 9 км. Температура падает примерно на 6 °C на каждый километр.'],
 [11,55,'Стратосфера','До высоты 50–55 км. Воздух разрежен и очень сухой, облаков почти нет. Внизу стратосферы — озоновый слой: он задерживает опасные ультрафиолетовые лучи Солнца.'],
 [55,85,'Мезосфера (верхние слои)','Очень разреженный воздух, самая холодная часть атмосферы (до −90 °C). Здесь сгорают метеоры — «падающие звёзды».'],
 [85,121,'Термосфера (верхние слои)','Воздуха почти нет. Здесь бывают полярные сияния. Верхние слои первыми защищают Землю от космического излучения и постепенно переходят в космос.']];
const layerOf=h=>LAYERS.find(L=>h>=L[0]&&h<L[1])||LAYERS[3];
function figLayers(o){o=o||{};const H0=210,Y=h=>H0-190*Math.sqrt(Math.max(0,h)/120),X=t=>200+t*0.85;let s='';
 const cols=['var(--accent)','var(--ok)','var(--hl)','var(--bad)'];
 LAYERS.forEach((L,i)=>{s+=RECT(0,Y(Math.min(L[1],120)),340,Y(L[0])-Y(Math.min(L[1],120)),{f:cols[i],fo:o.hl===L[2]?0.3:0.12});s+=TX(6,Y(L[0])-6,L[2].replace(' (верхние слои)',''),{fs:11.5,a:'start',halo:2});});
 s+=RECT(0,H0,340,8,{f:'var(--ok)',fo:0.6});
 [0,5,10,20,40,60,80,100,120].forEach(h=>{s+=LN(120,Y(h),126,Y(h),{sw:1})+TX(118,Y(h)+4,h+' км',{fs:9.5,a:'end',wt:500,c:'var(--muted)'});});
 s+=LN(126,H0,126,Y(120),{sw:1});
 [-80,-40,0,40].forEach(t=>{s+=LN(X(t),H0,X(t),H0+4,{sw:1})+TX(X(t),H0+15,(t>0?'+':t<0?'−':'')+Math.abs(t)+'°',{fs:9,wt:500,c:'var(--muted)'});});
 s+=PL([].concat(...TPROF.slice(1).map((p,i)=>{const a=TPROF[i];return Array.from({length:6},(_,k)=>{const hh=a[0]+(p[0]-a[0])*k/5;return [X(tAt(hh)),Y(hh)];});})),{c:'var(--bad)',sw:2.4});
 s+=TX(X(-56)-4,Y(25),'озоновый',{fs:9.5,a:'end',c:'var(--ok)',halo:2})+TX(X(-56)-4,Y(25)+11,'слой',{fs:9.5,a:'end',c:'var(--ok)',halo:2})+LN(X(-56)+2,Y(22),X(-56)+2,Y(32),{c:'var(--ok)',sw:5,op:0.6});
 s+=TX(330,Y(3)+4,'☁ облака',{fs:10,a:'end'})+TX(330,Y(10.5)+2,'✈ самолёты',{fs:10,a:'end'})+TX(330,Y(80),'☄ метеоры',{fs:10,a:'end'})+TX(330,Y(110),'полярные сияния',{fs:10,a:'end'});
 s+=TX(X(10),H0+28,'температура',{fs:10,c:'var(--bad)'});
 if(o.h!=null){const y=Y(o.h),x=X(tAt(o.h));s+=LN(126,y,340,y,{c:'var(--ink)',sw:1,dash:'4 3'})+CIR(x,y,5,{f:'var(--ink)'});}
 return SV(340,244,s,'Слои атмосферы',o.wd||340);}
