function figClim(T,P,o){o=o||{};const X=i=>46+i*23,maxP=Math.max(100,...P),Yp=p=>176-p/maxP*140;const tmin=Math.min(-10,...T),tmax=Math.max(30,...T);const Yt=t=>176-(t-tmin)/(tmax-tmin)*140;let s='';
 s+=LN(36,176,320,176,{sw:1})+LN(36,30,36,176,{sw:1})+LN(320,30,320,176,{sw:1});
 P.forEach((p,i)=>{s+=RECT(X(i)-8,Yp(p),16,176-Yp(p),{f:WATER,fo:0.45,s:'var(--accent-ink)',sw:0.5});s+=TX(X(i),190,MONS[i],{fs:10,wt:500,c:'var(--muted)'});});
 const st=(tmax-tmin)>40?20:10;for(let t=Math.ceil(tmin/st)*st;t<=tmax;t+=st){s+=LN(32,Yt(t),36,Yt(t),{sw:1})+TX(30,Yt(t)+4,(t>0?'+':t<0?'−':'')+Math.abs(t),{fs:9.5,a:'end',wt:500,c:'var(--bad)'});if(t===0)s+=LN(36,Yt(0),320,Yt(0),{sw:0.6,dash:'3 3',c:'var(--bad)'});}
 [0,maxP/2,maxP].forEach(p=>{s+=TX(324,Yp(p)+4,String(Math.round(p)),{fs:9.5,a:'start',wt:500,c:'var(--accent-ink)'});});
 s+=PL(T.map((t,i)=>[X(i),Yt(t)]),{c:'var(--bad)',sw:2.5});T.forEach((t,i)=>{s+=CIR(X(i),Yt(t),2.6,{f:'var(--bad)'});});
 s+=TX(36,22,'°C',{fs:10.5,c:'var(--bad)'})+TX(320,22,'мм',{fs:10.5,c:'var(--accent-ink)'})+(o.title?TX(178,16,o.title,{fs:12.5}):'');
 if(o.m!=null)s+=RECT(X(o.m)-11,28,22,150,{s:'var(--hl)',sw:2});
 return SV(340,196,s,'Климатограмма',340);}
