  let day=true;const g=id=>b.querySelector('#'+id);const u=()=>{g('bP').innerHTML=figBreeze(day);g('bT').innerHTML=day?'Днём суша нагревается быстрее воды → тёплый воздух над сушей поднимается → давление над сушей <b>ниже</b>. Ветер дует из «В» в «Н»: <b>с моря на сушу</b>.':'Ночью суша остывает быстрее → над сушей давление <b>выше</b>, над тёплым морем ниже. Ветер дует <b>с суши на море</b>.';setBtns(b,['bD','bN'],day?'bD':'bN');};
